// Dynamics on the Markov surfaces S_k: x² + y² + z² − xyz = k, over the complex numbers.
//
// A point (x, y, z) of S_k is the character of a pair of matrices A, B in SL(2,ℂ): x = tr A,
// y = tr B, z = tr AB, and k = tr[A, B] + 2. The mapping class group of the punctured torus acts on
// these characters, generated by the three Vieta involutions, each swapping the two roots of the
// equation in one coordinate:
//   s1: x ↦ yz − x,   s2: y ↦ xz − y,   s3: z ↦ xy − z.
// A word in them, applied over and over, is an automorphism of S_k; when the word uses all three
// letters it is usually hyperbolic, and its Julia set, the edge of the set of points whose orbits
// stay bounded, is a fractal (Cantat, "Bers and Hénon, Painlevé and Schrödinger", 2009).
//
// S_k is a complex surface, so a picture shows a slice of it, one complex dimension:
//   'surface': the conic z = z₀ in S_k. With z₀ = λ + 1/λ it reads (x − λy)(x − y/λ) = k − z₀², so
//              u = x − λy runs over ℂ* and parametrises it: y = (u − c/u) / (1/λ − λ), x = u + λy,
//              c = k − z₀². The picture is the u plane.
//   'line':    the line y = y₀, z = z₀ in ℂ³, the picture being the x plane. Its points lie on
//              different surfaces, k changing from pixel to pixel.

export const RADIUS = 1e8; // escape radius for the largest of |x|, |y|, |z|
const LOG_LOG_R = Math.log(Math.log(RADIUS));

// a word as a list of letters 0, 1, 2, with repeated letters cancelled (each s is an involution)
export function parseWord(w) {
  const out = [];
  for (const ch of String(w)) {
    if (ch !== '1' && ch !== '2' && ch !== '3') continue;
    const l = ch.charCodeAt(0) - 49;
    if (out.length && out[out.length - 1] === l) out.pop(); else out.push(l);
  }
  // cyclically too: the word is repeated, so its last letter meets its first
  while (out.length > 1 && out[0] === out[out.length - 1]) { out.shift(); out.pop(); }
  return out;
}

// the starting point for the pixel at w = (wr, wi) of the slice, into p = [xr, xi, yr, yi, zr, zi]
export function slicer(params) {
  if (params.slice === 'line') {
    const [yr, yi] = params.y0, [zr, zi] = params.z0;
    return (wr, wi, p) => { p[0] = wr; p[1] = wi; p[2] = yr; p[3] = yi; p[4] = zr; p[5] = zi; };
  }
  let [zr, zi] = params.z0;
  // λ = (z₀ + √(z₀² − 4)) / 2; at z₀ = ±2 the conic degenerates into two lines, so move off it
  let dr = zr * zr - zi * zi - 4, di = 2 * zr * zi;
  if (Math.hypot(dr, di) < 1e-12) { zi += 1e-9; dr = zr * zr - zi * zi - 4; di = 2 * zr * zi; }
  const m = Math.hypot(dr, di), sr = Math.sqrt((m + dr) / 2), si = Math.sign(di || 1) * Math.sqrt((m - dr) / 2);
  const lr = (zr + sr) / 2, li = (zi + si) / 2;
  const ln = lr * lr + li * li, ir = lr / ln, ii = -li / ln;   // 1/λ
  const er = ir - lr, ei = ii - li, en = er * er + ei * ei;    // 1/λ − λ
  const [kr, ki] = params.k;
  const cr = kr - (zr * zr - zi * zi), ci = ki - 2 * zr * zi;  // c = k − z₀²
  return (wr, wi, p) => {
    // y = (u − c/u) / (1/λ − λ), x = u + λy
    const un = wr * wr + wi * wi || 1e-300;
    const qr = wr - (cr * wr + ci * wi) / un, qi = wi - (ci * wr - cr * wi) / un;
    const yr = (qr * er + qi * ei) / en, yi = (qi * er - qr * ei) / en;
    p[0] = wr + lr * yr - li * yi; p[1] = wi + lr * yi + li * yr;
    p[2] = yr; p[3] = yi; p[4] = zr; p[5] = zi;
  };
}

// Applies the word over and over to p, letter by letter, until the largest coordinate passes
// RADIUS or maxIt words are done. Returns the escape time in words, smoothed between the letter
// before and the letter after the escape on a log-log scale (the growth is doubly exponential),
// or −1 for an orbit still bounded.
export function escape(p, word, maxIt) {
  let xr = p[0], xi = p[1], yr = p[2], yi = p[3], zr = p[4], zi = p[5];
  const n = word.length;
  let prev = Math.max(xr * xr + xi * xi, yr * yr + yi * yi, zr * zr + zi * zi);
  for (let it = 0; it < maxIt; it++) {
    for (let j = 0; j < n; j++) {
      const l = word[j];
      if (l === 0) { const tr = yr * zr - yi * zi - xr, ti = yr * zi + yi * zr - xi; xr = tr; xi = ti; }
      else if (l === 1) { const tr = xr * zr - xi * zi - yr, ti = xr * zi + xi * zr - yi; yr = tr; yi = ti; }
      else { const tr = xr * yr - xi * yi - zr, ti = xr * yi + xi * yr - zi; zr = tr; zi = ti; }
      const m2 = Math.max(xr * xr + xi * xi, yr * yr + yi * yi, zr * zr + zi * zi);
      if (!(m2 <= RADIUS * RADIUS)) {
        // log log |m| before and after this letter, and where log log R falls between them
        const a = Math.log(Math.max(0.5 * Math.log(Math.max(prev, 1.0000001)), 1e-9));
        const b = isFinite(m2) ? Math.log(0.5 * Math.log(m2)) : a + 1;
        const f = b > a ? Math.min(1, Math.max(0, (LOG_LOG_R - a) / (b - a))) : 1;
        return it + (j + f) / n;
      }
      prev = m2;
    }
  }
  return -1;
}
